contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        require(true);

        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool initializedSucceeded;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initializedSucceeded = false; } else { initializedSucceeded = true; }

        assert(reverted ? (afterMinSum == beforeMinSum && afterMinSum == 0) : (afterMinSum == _val && initializedSucceeded));
    }

    receive() external payable {}
}

